insert into public.item_options select * from jsonb_populate_recordset(null::public.item_options,'[{"id": "ec89759b-4b61-53a9-91d4-8091a0ecec96", "item_id": "05d0634b-0415-51ff-a02a-44ebdd9c7ad1", "content_en": null, "content_hy": "Նյութերի ինքնաբերական խառնումը, երբ մի նյութի մոլեկուլները ներթափանցում են մյուս նյութի միջմոլեկուլային տարածություններ։", "option_key": "A", "display_order": 1}, {"id": "296320bd-e620-57e0-9cd1-c2c9ca3d133f", "item_id": "05d0634b-0415-51ff-a02a-44ebdd9c7ad1", "content_en": null, "content_hy": "Միայն արտաքին խառնիչով նյութերի մեծ մասերի տեղաշարժը։", "option_key": "B", "display_order": 2}, {"id": "00c4c14f-6436-5c14-93bc-be9d9eb92970", "item_id": "05d0634b-0415-51ff-a02a-44ebdd9c7ad1", "content_en": null, "content_hy": "Տաքացնելիս նյութի՝ պինդ վիճակից հեղուկ վիճակի անցումը։", "option_key": "C", "display_order": 3}, {"id": "5e762a15-5216-54dd-9645-cc95c21af886", "item_id": "05d0634b-0415-51ff-a02a-44ebdd9c7ad1", "content_en": null, "content_hy": "Երկու նյութերից նոր նյութ առաջացնող քիմիական փոխազդեցությունը։", "option_key": "D", "display_order": 4}, {"id": "faf860dd-8ea9-5921-8ade-42d0b501ef6d", "item_id": "71bc6b7c-9064-5382-ae7b-46a71836cfcd", "content_en": null, "content_hy": "Պղնձարջասպի լուծույթը, ջրից թեթև լինելով, ամբողջ շերտով բարձրացել է վերև։", "option_key": "A", "display_order": 1}, {"id": "ee904a61-e5d4-58c4-abd2-f2b0aac394be", "item_id": "71bc6b7c-9064-5382-ae7b-46a71836cfcd", "content_en": null, "content_hy": "Ջրի և լուծույթի մոլեկուլների անկանոն շարժման պատճառով դրանք փոխադարձաբար ներթափանցել են միմյանց միջմոլեկուլային տարածություններ։", "option_key": "B", "display_order": 2}, {"id": "6f8cf522-6531-52cb-a235-e9acb5289dca", "item_id": "71bc6b7c-9064-5382-ae7b-46a71836cfcd", "content_en": null, "content_hy": "Կապույտ գույնը ժամանակի ընթացքում պարզապես տարածվել է՝ առանց որևէ մոլեկուլի տեղաշարժի։", "option_key": "C", "display_order": 3}, {"id": "a564fa6f-a037-56e7-ac25-a7f7f08c1118", "item_id": "71bc6b7c-9064-5382-ae7b-46a71836cfcd", "content_en": null, "content_hy": "Ջրի մոլեկուլները կանգ են առել, իսկ լուծույթը մեկ ամբողջական շերտով զբաղեցրել է անոթը։", "option_key": "D", "display_order": 4}, {"id": "1ecf6e04-063d-5f5e-96fd-51e9f0b4c6b3", "item_id": "d704d8a2-f0ef-523f-9a47-f68f4a1243bc", "content_en": null, "content_hy": "Աղը ծանրության ուժից ամբողջությամբ ընկնում է միայն անոթի հատակին։", "option_key": "A", "display_order": 1}, {"id": "a6a5e995-0ea5-5bd7-b17d-b9c4d5abda06", "item_id": "d704d8a2-f0ef-523f-9a47-f68f4a1243bc", "content_en": null, "content_hy": "Աղաջուրը բանջարեղենը ներսից հալեցնում է։", "option_key": "B", "display_order": 2}, {"id": "34fb3caa-6b8c-56e3-a09f-6bd00301bace", "item_id": "d704d8a2-f0ef-523f-9a47-f68f4a1243bc", "content_en": null, "content_hy": "Լուծված աղի մասնիկները շարունակական անկանոն շարժման հետևանքով ներթափանցում են բանջարեղենի մեջ։ Սա դիֆուզիա է։", "option_key": "C", "display_order": 3}, {"id": "340ed1f6-9fc8-52b3-a459-e13f78a040ae", "item_id": "d704d8a2-f0ef-523f-9a47-f68f4a1243bc", "content_en": null, "content_hy": "Աղը բանջարեղենի ներսում առաջանում է որպես նոր քիմիական նյութ։", "option_key": "D", "display_order": 4}, {"id": "6e5b907a-fcef-5e3e-a3e7-379bbd99c8c2", "item_id": "26d99215-00c8-5dd3-9ff6-0cfd7c99aee8", "content_en": null, "content_hy": "Թթվածինը արյան մեջ է անցնում միայն այն պատճառով, որ սիրտը մեխանիկորեն խառնում է օդն ու արյունը։", "option_key": "A", "display_order": 1}, {"id": "0486f748-54a8-5ef0-bc67-cfa2580aeb4d", "item_id": "26d99215-00c8-5dd3-9ff6-0cfd7c99aee8", "content_en": null, "content_hy": "Օդի ամբողջ շերտը մեկ զանգվածով մտնում է արյան անոթների մեջ։", "option_key": "B", "display_order": 2}, {"id": "18dc2420-90ac-5478-b604-b17283c3a324", "item_id": "26d99215-00c8-5dd3-9ff6-0cfd7c99aee8", "content_en": null, "content_hy": "Արյան մեջ թթվածինը առաջանում է մեկ այլ նյութի քիմիական քայքայումից։", "option_key": "C", "display_order": 3}, {"id": "1120bbb4-1878-5fdd-87d7-fb9f60d700c2", "item_id": "26d99215-00c8-5dd3-9ff6-0cfd7c99aee8", "content_en": null, "content_hy": "Թթվածնի մասնիկները իրենց շարժման հետևանքով ներթափանցում են օդից արյան մեջ՝ դիֆուզիայի միջոցով։", "option_key": "D", "display_order": 4}]'::jsonb);
