insert into public.misconceptions select * from jsonb_populate_recordset(null::public.misconceptions,'[{"id": "ce5cb164-1c5c-593b-9c34-30f11a9df48e", "code": "diffusion_requires_external_mixing", "status": "active", "skill_id": "a3d83a26-87c0-53be-9c72-43eb61d42f86", "title_hy": "Դիֆուզիան միայն արտաքին խառնումով հնարավոր համարելը", "created_at": "2026-10-01T17:10:21.840085+00:00", "updated_at": "2026-10-05T17:56:42.802658+00:00", "description_hy": "Սովորողը կարծում է, թե նյութերը կարող են խառնվել միայն խառնելու, պոմպելու կամ մեկ ամբողջական շերտը տեղաշարժելու միջոցով և անտեսում է մասնիկների ինքնաբերական շարժումը։"}, {"id": "8583f735-fd5a-5602-b9fd-0fa0f264bf0e", "code": "diffusion_is_bulk_layer_motion", "status": "active", "skill_id": "a3d83a26-87c0-53be-9c72-43eb61d42f86", "title_hy": "Դիֆուզիան նյութի ամբողջական շերտի տեղաշարժ համարելը", "created_at": "2026-10-01T17:10:21.840085+00:00", "updated_at": "2026-10-05T17:56:04.11585+00:00", "description_hy": "Սովորողը դիֆուզիայի մասնիկային փոխադարձ ներթափանցումը փոխարինում է մի նյութի ամբողջ շերտի միակողմանի տեղաշարժով կամ ծանրության ազդեցությամբ։"}, {"id": "7446d7e2-298b-5766-97ff-a6b0017cd633", "code": "diffusion_without_particle_transfer", "status": "active", "skill_id": "a3d83a26-87c0-53be-9c72-43eb61d42f86", "title_hy": "Դիֆուզիան առանց մասնիկների տեղափոխության պատկերացնելը", "created_at": "2026-10-01T17:10:21.840085+00:00", "updated_at": "2026-10-05T17:57:35.149294+00:00", "description_hy": "Սովորողը տեսանելի գույնի կամ սահմանագծի փոփոխությունը համարում է ինքնուրույն երևույթ և չի կապում այն մասնիկների շարժման ու փոխադարձ ներթափանցման հետ։"}, {"id": "85912205-f9cb-53ac-adb8-3fa2c28612c4", "code": "diffusion_is_phase_or_chemical_change", "status": "active", "skill_id": "a3d83a26-87c0-53be-9c72-43eb61d42f86", "title_hy": "Դիֆուզիան վիճակի կամ քիմիական փոփոխության հետ շփոթելը", "created_at": "2026-10-01T17:10:21.840085+00:00", "updated_at": "2026-10-05T17:56:24.254456+00:00", "description_hy": "Սովորողը դիֆուզիան նույնացնում է հալման, քիմիական ռեակցիայի կամ նոր նյութի առաջացման հետ։"}]'::jsonb);
