insert into public.item_template_remediation_guides select * from jsonb_populate_recordset(null::public.item_template_remediation_guides,'[{"id": "d42679aa-546a-5727-b419-2dfc5c2858e0", "status": "published", "metadata": {"sprint": "15B.7", "learnerVisible": false, "referenceMetadata": {"textbookSha256": "d8404d572f145d4afe924d0b8af900b3d9ed085a37893594667ab07a2ec12904", "textbookLocator": "Ֆիզիկա 7 (2023), Գլուխ II, §10, տպագիր էջեր 30-32, նկարներ 30-31", "programmeOutcomeLocator": "7-րդ դասարան / Թեմա 2 / Վերջնարդյունքներ / Պարտադիր 1(4)"}}, "title_hy": "Ինչպե՞ս բացատրել դիֆուզիան օրինակով", "hint_1_hy": "Փնտրի՛ր երկու հիմնական հատկանիշ. ինքնաբերական խառնում և մոլեկուլների փոխադարձ ներթափանցում։", "hint_2_hy": "Բացատրության մեջ նշի՛ր ոչ միայն դիտվող արդյունքը, այլև մոլեկուլների անկանոն շարժումը, որը հանգեցնում է այդ երևույթին։", "created_at": "2026-10-01T17:10:21.840085+00:00", "updated_at": "2026-10-05T14:19:01.208397+00:00", "strategy_hy": "Նախ որոշի՛ր՝ արդյոք երկու նյութերն ինքնաբերաբար խառնվում են առանց արտաքին միջամտության։ Այնուհետև նկարագրի՛ր մասնիկային մեխանիզմը. երկու նյութերի մոլեկուլներն անընդհատ շարժվում են անկանոն կերպով և փոխադարձաբար ներթափանցում միմյանց միջմոլեկուլային տարածություններ։ Օրինակի տեսանելի արդյունքը կապի՛ր հենց այդ մասնիկային շարժման հետ։ Դիֆուզիան մի՛ շփոթիր նյութի զանգվածային տեղաշարժի, ագրեգատային վիճակի փոփոխության կամ քիմիական ռեակցիայի հետ։", "guide_version": 3, "item_template_id": "4f6a4244-17d1-596d-a271-bcd38e7d1a33", "worked_example_hy": "Օրինակ՝ պղնձարջասպի լուծույթի և ջրի սահմանը ժամանակի ընթացքում ջնջվում (լղոզվում) է, քանի որ երկու հեղուկների մոլեկուլներն անկանոն շարժվում և փոխադարձաբար ներթափանցում են միմյանց միջմոլեկուլային տարածություններ։ Արդյունքում ամբողջ հեղուկը դառնում է համաչափ բաց կապույտ գույնի՝ առանց արտաքին միջամտության։", "trigger_error_code": null, "allowed_parameter_keys": []}]'::jsonb);
insert into skill_outcomes select id,(select id from learning_outcomes limit 1) from skills;
